from __future__ import annotations

__doc__ = """
Python-host backend definitions for ADAAs and coefficient storage.

This module groups the pure Python host-side backends:

- :class:`PythonCoeffBackend` for plain Python list storage,
- :class:`PythonRA` / :class:`PythonCA` as the user-facing pure-Python ADAAs.

The Python backend stores coefficient data as plain Python lists and converts
to NumPy only on request through the generic ADAA conversion layer.
"""

from typing import Any

import numpy as np

from ....adaa import ComplexArrayADAA, ImagArrayADAA, RealArrayADAA
from ....coeffbackend import CoeffBackend


class PythonCoeffBackend(CoeffBackend):
    """Coefficient backend storing host arrays as Python lists."""

    def coeff_new_array(self, size: int, dtype: str):
        match dtype:
            case "f32":
                return [0.0 for _ in range(size)]
            case "f64":
                return [0.0 for _ in range(size)]
            case "i32":
                return [0 for _ in range(size)]
            case "i64":
                return [0 for _ in range(size)]
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_from_numpy(
        self,
        coeff_like: Any,
        nparray: np.ndarray,
        size: int,
        dtype: str,
    ) -> None:
        if dtype in ("f32", "f64"):
            if nparray.dtype in [np.float32, np.float64]:
                for num, val in enumerate(nparray):
                    coeff_like[num] = float(val)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        elif dtype in ("i32", "i64"):
            if nparray.dtype in [np.int32, np.int64]:
                for num, val in enumerate(nparray):
                    coeff_like[num] = int(val)
            else:
                raise ValueError(
                    f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                )
        else:
            raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_numpy(
        self, coeff_like: Any, size: int, dtype: str
    ) -> np.ndarray:
        match dtype:
            case "f32":
                return np.array(coeff_like, dtype=np.float32)
            case "f64":
                return np.array(coeff_like, dtype=np.float64)
            case "i32":
                return np.array(coeff_like, dtype=np.int32)
            case "i64":
                return np.array(coeff_like, dtype=np.int64)
            case _:
                raise ValueError(f"dtype {dtype} not understood")

    def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str):
        del size
        zero = 0.0 if dtype in ("f32", "f64") else 0
        for num in range(len(coeff_like)):
            coeff_like[num] = zero

    def coeff_linop(
        self,
        arr_r: Any,
        /,
        scal_a: float | None,
        arr_x: Any,
        scal_b: float | None,
        arr_y: Any,
        *,
        size: int,
        dtype: str,
        inplace: bool = False,
    ):
        del dtype
        if arr_r is None:
            return
        if not inplace and arr_x is None:
            for num in range(size):
                arr_r[num] = 0
        elif arr_x is not None:
            match (inplace, scal_a):
                case (True, None):
                    for num in range(size):
                        arr_r[num] += arr_x[num]
                case (True, scal_a):
                    for num in range(size):
                        arr_r[num] += scal_a * arr_x[num]
                case (False, None):
                    for num in range(size):
                        arr_r[num] = arr_x[num]
                case (False, scal_a):
                    for num in range(size):
                        arr_r[num] = scal_a * arr_x[num]

        match (scal_b, arr_y):
            case (None, None):
                return
            case (_, None):
                return
            case (None, arr_y):
                for num in range(size):
                    arr_r[num] += arr_y[num]
            case (scal_b, arr_y):
                for num in range(size):
                    arr_r[num] += scal_b * arr_y[num]


class PythonCA(
    ComplexArrayADAA,
    backend=PythonCoeffBackend(),
    identifier="PYTHON",
    is_anchor=True,
):
    """Complex ADAA for the pure-Python backend."""


class PythonRA(
    RealArrayADAA,
    backend=PythonCoeffBackend(),
    identifier="PYTHON",
    is_anchor=True,
):
    """Real ADAA for the pure-Python backend."""


class PythonIA(
    ImagArrayADAA,
    backend=PythonCoeffBackend(),
    identifier="PYTHON",
    is_anchor=True,
):
    """Purely imaginary ADAA for the pure-Python backend."""


__all__ = [
    "PythonCoeffBackend",
    "PythonCA",
    "PythonRA",
    "PythonIA",
]
